-- =============================================================================
-- 542 — LE CAHIER D'EXERCICES DE 1RE (partie 30)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 542 --niveau 1re --fichiers physique-chimie-maths.n2,physique-chimie-sante.n1,physique-chimie-sante.n2 --suffixe 30 > supabase/contenu/542_exercices_1re_30.sql
--
-- 69 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   physique-chimie-maths.n2  21 exercices · 7 chapitres
--   physique-chimie-sante.n1  24 exercices · 8 chapitres
--   physique-chimie-sante.n2  24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ad8f5af9-afaa-5f6b-bf46-9fc7fd93334f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le clou de fer dans le sulfate de cuivre","competence":"experimenter","situation":"En TP, Rayan plonge un clou de fer dans une solution de sulfate de cuivre. Au bout de quelques minutes, le clou se couvre d’un dépôt de cuivre métallique. Il consulte les demi-équations de trois couples.","documents":[{"id":"couples","type":"tableau","titre":"Trois couples oxydant/réducteur","colonnes":["Couple","Demi-équation"],"lignes":[["Fe²⁺/Fe","Fe²⁺ + 2 e⁻ = Fe"],["Cu²⁺/Cu","Cu²⁺ + 2 e⁻ = Cu"],["Zn²⁺/Zn","Zn²⁺ + 2 e⁻ = Zn"]],"enteteLignes":true,"source":"Demi-équations du cours"}],"questions":[{"enonce":"Du cuivre métallique se dépose : touche le couple dont l’oxydant a été consommé.","aide":"Le métal qui se dépose est la forme réduite du couple.","type":"zone","document":"couples","multiple":false},{"enonce":"Combien d’électrons échange chaque ion Cu²⁺ en devenant Cu ?","aide":"Lis la demi-équation du couple Cu²⁺/Cu.","type":"nombre"},{"enonce":"Complète la phrase sur le rôle du fer.","aide":"Le fer devient Fe²⁺ : gagne-t-il ou perd-il des électrons ?","type":"trous","segments":["Le fer ",0," deux électrons : il subit une ",1,"."],"banque":["oxydation","réduction","capte","cède"]},{"enonce":"Quelle est l’équation de la réaction ?","aide":"On additionne l’oxydation du fer et la réduction des ions cuivre, pour que les électrons s’éliminent.","type":"choix","options":[{"id":"a","texte":"Fe²⁺ + Cu²⁺ → Fe + Cu : les deux captent 2 électrons"},{"id":"b","texte":"Fe + Cu → Fe²⁺ + Cu²⁺ : aucun électron échangé"},{"id":"c","texte":"Fe + Cu²⁺ → Fe²⁺ + Cu : le fer cède 2 électrons"},{"id":"d","texte":"Fe²⁺ + Cu → Fe + Cu²⁺ : le cuivre cède 2 électrons"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Le dépôt est du cuivre Cu : les ions Cu²⁺ (l’oxydant) ont été consommés. Le couple est **Cu²⁺/Cu**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Cu²⁺ + **2** e⁻ = Cu : chaque ion capte 2 électrons."},{"cle":{"type":"trous","trous":[["cede"],["oxydation"]]},"affichage":"cède · oxydation","explication":"Le fer **cède** deux électrons (Fe → Fe²⁺ + 2 e⁻) : c’est une **oxydation**, il joue le rôle de réducteur."},{"cle":{"type":"choix","ids":["c"]},"explication":"Oxydation : Fe → Fe²⁺ + 2 e⁻. Réduction : Cu²⁺ + 2 e⁻ → Cu. Bilan : **Fe + Cu²⁺ → Fe²⁺ + Cu**."}]$ex$::jsonb),
  ('ad8f5af9-afaa-5f6b-bf46-9fc7fd93334f'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le bloc de zinc sur la coque","competence":"analyser-document","situation":"Un chantier naval teste trois montages en eau de mer pendant un mois. Pour chaque montage, on pèse la perte de masse du fer. Masse molaire du zinc : M(Zn) = 65 g/mol.","documents":[{"id":"pertes","type":"tableau","titre":"Pertes de masse après un mois en eau de mer","colonnes":["Montage","Perte du fer (g)","Perte du 2ᵉ métal (g)"],"lignes":[["Fer seul","4,8","—"],["Fer relié à du zinc","0,1","3,9"],["Fer relié à du cuivre","7,2","0,0"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche le montage où le fer perd le plus de masse.","aide":"Compare les valeurs de la colonne « Perte du fer ».","type":"zone","document":"pertes","multiple":false},{"enonce":"Pourquoi le bloc de zinc protège-t-il le fer ?","aide":"Regarde qui perd de la masse quand le zinc est relié au fer.","type":"choix","options":[{"id":"a","texte":"Le zinc isole le fer de l’eau comme une peinture"},{"id":"b","texte":"Le zinc est moins réducteur que le fer"},{"id":"c","texte":"Le zinc empêche le dioxygène de se dissoudre"},{"id":"d","texte":"Le zinc est plus réducteur : il s’oxyde à la place du fer"}],"multiple":false},{"enonce":"Combien d’électrons cède chaque atome de zinc (Zn → Zn²⁺ + …) ?","aide":"Regarde la charge de l’ion Zn²⁺.","type":"nombre"},{"enonce":"Quelle quantité de zinc a été consommée (n = m / M), en mol ? Arrondis au centième.","aide":"Utilise la perte de masse de 3,9 g.","type":"nombre","unite":"mol"},{"enonce":"Quelle quantité d’électrons ont ainsi été fournies au fer, en mol ?","aide":"Chaque atome de zinc fournit 2 électrons.","type":"nombre","unite":"mol"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le fer relié au cuivre perd **7,2 g** : le cuivre, moins réducteur, ne le protège pas, et le fer s’oxyde même plus vite."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le zinc cède ses électrons plus facilement que le fer : il se corrode **à la place du fer**. C’est le principe de l’anode sacrificielle."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"Zn → Zn²⁺ + **2** e⁻ : chaque atome de zinc cède 2 électrons."},{"cle":{"type":"nombre","valeur":0.06,"tolerance":0.002},"affichage":"0,06 mol","explication":"n = 3,9 / 65 = **0,060 mol**."},{"cle":{"type":"nombre","valeur":0.12,"tolerance":0.004},"affichage":"0,12 mol","explication":"n(e⁻) = 2 × 0,060 = **0,12 mol**."}]$ex$::jsonb),
  ('ad8f5af9-afaa-5f6b-bf46-9fc7fd93334f'::uuid, 3, 3, 15, 50, 5,
