:[["Tension de la pile","1,1 V"],["Perte de masse de la plaque de zinc","0,65 g"],["M(Zn)","65 g/mol"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’électrode où a lieu l’oxydation (l’anode).","aide":"L’oxydation est une perte d’électrons : quel métal en perd ?","type":"zone","document":"pile","multiple":false},{"enonce":"Dans le fil extérieur, dans quel sens circulent les électrons ?","aide":"Les électrons sont libérés à l’anode et consommés à la cathode.","type":"choix","options":[{"id":"a","texte":"De la plaque de cuivre vers la plaque de zinc"},{"id":"b","texte":"De la plaque de zinc vers la plaque de cuivre"},{"id":"c","texte":"Ils ne circulent pas dans le fil"},{"id":"d","texte":"Ils traversent le pont salin"}],"multiple":false},{"enonce":"Complète le bilan de la pile.","aide":"Les ions Cu²⁺ captent des électrons à la cathode.","type":"trous","segments":["Zn + Cu²⁺ → Zn²⁺ + ",0],"banque":["e⁻","Cu²⁺","Zn","Cu"]},{"enonce":"Quelle quantité de zinc a été consommée (n = m / M), en mol ?","aide":"Utilise la perte de masse et la masse molaire du tableau.","type":"nombre","unite":"mol"},{"enonce":"Quelle quantité d’électrons la pile a-t-elle fait circuler dans le fil, en mol ?","aide":"Chaque atome de zinc cède 2 électrons.","type":"nombre","unite":"mol"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"À l’**anode**, le zinc s’oxyde : Zn → Zn²⁺ + 2 e⁻. La plaque de zinc perd de la masse."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le zinc libère les électrons, que le cuivre consomme : ils vont **du zinc vers le cuivre** par le fil (le courant conventionnel va en sens inverse)."},{"cle":{"type":"trous","trous":[["cu"]]},"affichage":"Cu","explication":"Les ions Cu²⁺ sont réduits en cuivre métallique : **Zn + Cu²⁺ → Zn²⁺ + Cu**."},{"cle":{"type":"nombre","valeur":0.01,"tolerance":0.0005},"affichage":"0,01 mol","explication":"n = 0,65 / 65 = **0,010 mol**."},{"cle":{"type":"nombre","valeur":0.02,"tolerance":0.001},"affichage":"0,02 mol","explication":"n(e⁻) = 2 × 0,010 = **0,020 mol**."}]$ex$::jsonb),
