 |z₂| = 4 ?","aide":"Les vecteurs OM₁ et OM₂ ne pointent pas dans la même direction.","type":"choix","options":[{"id":"a","texte":"Les deux tensions ont des fréquences différentes"},{"id":"b","texte":"On a fait une erreur d’arrondi"},{"id":"c","texte":"Les deux tensions ne sont pas en phase"},{"id":"d","texte":"Le module d’une somme est toujours la moyenne"}],"multiple":false}]}$ex$::jsonb,
