  ('c51cb50e-8260-5c0a-b55a-d1604ffdde1f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le bilan de repos de Samia","competence":"calculer","situation":"Samia, 16 ans, passe un bilan de santé avant de s’inscrire au club d’athlétisme. L’infirmière note ses mesures de repos sur une fiche. Tu vas en tirer son débit cardiaque et interpréter sa tension.","documents":[{"id":"fiche","type":"fiche","modele":"ticket","titre":"Fiche de bilan","entete":"Bilan de santé — mesures de repos","sousTitre":"Samia, 16 ans","emoji":"🩺","lignes":[{"texte":"Fréquence cardiaque","valeur":"72 battements/min","id":"z1"},{"texte":"Volume d’éjection systolique","valeur":"75 mL","id":"z2"},{"separateur":true},{"texte":"Tension artérielle","valeur":"13/8","id":"z3"}],"pied":"Fiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui donne le volume de sang éjecté par le cœur à chaque battement.","aide":"Le volume d’éjection systolique (VES) est un volume : il s’exprime en mL.","type":"zone","document":"fiche","multiple":false},{"enonce":"Calcule le débit cardiaque de Samia, en litres par minute (DC = fC × VES).","aide":"Multiplie les deux valeurs de la fiche, puis convertis les mL en L (1 L = 1 000 mL).","type":"nombre","unite":"L/min"},{"enonce":"Sa tension est notée « 13/8 ». Que peut-on en dire ?","aide":"Le premier nombre est la tension systolique, le second la diastolique. Compare chacun à 14 et à 9.","type":"choix","options":[{"id":"a","texte":"Elle atteint le seuil d’hypertension, 14/9"},{"id":"b","texte":"Elle reste en dessous du seuil d’hypertension, 14/9"},{"id":"c","texte":"La tension diastolique est de 13 cmHg"},{"id":"d","texte":"La tension systolique est de 8 cmHg"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **volume d’éjection systolique (VES)** est le volume de sang expulsé à chaque contraction : ici 75 mL."},{"cle":{"type":"nombre","valeur":5.4,"tolerance":0.05},"affichage":"5,4 L/min","explication":"DC = fC × VES = 72 × 75 = 5 400 mL/min, soit **5,4 L/min**. C’est un ordre de grandeur normal au repos (environ 5 L/min)."},{"cle":{"type":"choix","ids":["b"]},"explication":"13 cmHg de systolique et 8 cmHg de diastolique : **13/8 est sous le seuil 14/9** de l’hypertension (qui se juge sur des mesures répétées)."}]$ex$::jsonb),
  ('c51cb50e-8260-5c0a-b55a-d1604ffdde1f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La poche de perfusion de M. Garnier","competence":"modeliser","situation":"À l’hôpital, l’infirmière installe une perfusion à M. Garnier. Elle accroche la poche à 0,80 m au-dessus de la veine du bras. Pour que le liquide entre dans la veine, sa pression doit dépasser celle du sang veineux.","documents":[{"id":"perf","type":"schema","titre":"La perfusion de M. Garnier (hors échelle)","largeur":320,"hauteur":290,"elements":[{"forme":"rect","x":30,"y":270,"l":70,"h":8,"arrondi":3,"teinte":"gris","motif":"plein"},{"forme":"ligne","de":[60,270],"a":[60,20],"teinte":"gris"},{"forme":"ligne","de":[60,20],"a":[112,20],"teinte":"gris"},{"forme":"ligne","de":[112,20],"a":[112,34],"teinte":"gris"},{"forme":"rect","x":85,"y":34,"l":54,"h":66,"arrondi":12,"teinte":"bleu","motif":"clair","id":"z1","zone":true,"texte":"Poche"},{"forme":"ligne","de":[112,100],"a":[112,112],"teinte":"encre"},{"forme":"rect","x":100,"y":112,"l":24,"h":28,"arrondi":6,"teinte":"bleu","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":112,"cy":126,"r":3,"teinte":"bleu","motif":"plein"},{"forme":"ligne","de":[112,140],"a":[112,225],"teinte":"encre"},{"forme":"ligne","de":[112,225],"a":[212,225],"teinte":"encre"},{"forme":"rect","x":212,"y":203,"l":96,"h":44,"arrondi":14,"teinte":"ambre","motif":"clair","id":"z3","zone":true},{"forme":"ligne","de":[226,225],"a":[300,225],"teinte":"bleu"},{"forme":"texte","x":262,"y":262,"texte":"Bras","taille":"petit","ancre":"milieu"},{"forme":"texte","x":262,"y":218,"texte":"veine","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"ligne","de":[140,100],"a":[188,100],"style":"pointilles","teinte":"gris"},{"forme":"ligne","de":[176,102],"a":[176,223],"fleche":"deux","teinte":"violet"},{"forme":"texte","x":180,"y":168,"texte":"h = 0,80 m","taille":"petit","gras":true,"ancre":"debut"}],"source":"Schéma simplifié pour l’exercice"},{"id":"donnees","type":"texte","genre":"consigne","titre":"Données","blocs":["La solution a la masse volumique de l’eau : ρ = 1 000 kg/m³. Intensité de la pesanteur : g = 9,81 N/kg.","La pression du sang veineux dépasse la pression atmosphérique de 1 200 Pa.","Relation : P = ρ × g × h."],"source":"Données écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’élément dont la hauteur au-dessus du bras fixe la pression du liquide à l’entrée de la veine.","aide":"C’est le réservoir de liquide, accroché en hauteur.","type":"zone","document":"perf","multiple":false},{"enonce":"Calcule la pression due à la hauteur h = 0,80 m, en pascals, arrondie à la centaine.","aide":"Écris d’abord P = ρ × g × h, puis remplace par les trois valeurs sans oublier les unités.","type":"nombre","unite":"Pa"},{"enonce":"La perfusion peut-elle s’écouler dans la veine ?","aide":"Compare la pression du liquide à celle du sang veineux : laquelle est la plus grande ?","type":"choix","options":[{"id":"a","texte":"Oui : 7 800 Pa dépasse largement les 1 200 Pa du sang veineux"},{"id":"b","texte":"Non : il faudrait au moins 10 000 Pa pour entrer dans une veine"},{"id":"c","texte":"Non : la pression du sang veineux est toujours supérieure"},{"id":"d","texte":"Oui : la pression du liquide n’a aucun rôle ici"}],"multiple":false},{"enonce":"À quelle hauteur minimale (en cm, arrondie à l’unité) faudrait-il placer la poche pour égaler la pression du sang veineux ?","aide":"Isole h dans P = ρ × g × h, avec P = 1 200 Pa, puis convertis des mètres en centimètres.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La pression ne dépend que de la hauteur de liquide au-dessus de la veine : c’est le niveau de **la poche** qui compte."},{"cle":{"type":"nombre","valeur":7800,"tolerance":50},"affichage":"7800 Pa","explication":"P = 1 000 × 9,81 × 0,80 = 7 848 Pa, soit environ **7 800 Pa**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le liquide pousse à environ 7 800 Pa contre 1 200 Pa pour le sang veineux : **il entre dans la veine**. Une poche trop basse ne coulerait plus."},{"cle":{"type":"nombre","valeur":12,"tolerance":0.5},"affichage":"12 cm","explication":"h = P / (ρ × g) = 1 200 / (1 000 × 9,81) ≈ 0,122 m, soit **12 cm** : en dessous, la perfusion ne coule plus."}]$ex$::jsonb),
  ('c51cb50e-8260-5c0a-b55a-d1604ffdde1f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une artère carotide rétrécie","competence":"analyser-document","situation":"M. Roche, 62 ans, passe un écho-doppler de l’artère carotide : le médecin repère un rétrécissement. Il lui demande aussi de noter sa tension pendant trois jours, matin et soir.","documents":[{"id":"artere","type":"schema","titre":"Coupe de la carotide de M. Roche (hors échelle)","largeur":320,"hauteur":190,"elements":[{"forme":"polygone","points":[[20,40],[300,40],[300,160],[20,160]],"teinte":"corail","motif":"clair"},{"forme":"rect","x":20,"y":40,"l":90,"h":120,"teinte":"corail","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":140,"y":84,"l":50,"h":32,"teinte":"corail","motif":"plein","id":"z2","zone":true},{"forme":"polygone","points":[[110,40],[140,84],[190,84],[220,40]],"teinte":"ambre","motif":"plein","id":"z3","zone":true},{"forme":"polygone","points":[[110,160],[140,116],[190,116],[220,160]],"teinte":"ambre","motif":"plein","id":"z4","zone":true},{"forme":"ligne","de":[30,100],"a":[80,100],"fleche":"fin","teinte":"encre"},{"forme":"ligne","de":[230,100],"a":[290,100],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":160,"y":30,"texte":"dépôt de graisse","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":160,"y":182,"texte":"sens du sang →","taille":"petit","italique":true,"ancre":"milieu"}],"source":"Schéma simplifié, hors échelle"},{"id":"tension","type":"tableau","titre":"Automesures de tension (cmHg)","colonnes":["Jour","Matin","Soir"],"lignes":[["Lundi","14/9","15/9"],["Mardi","14/10","14/9"],["Mercredi","15/9","16/10"]],"enteteLignes":true,"source":"Relevés écrits pour l’exercice"}],"questions":[{"enonce":"Sur le schéma, touche l’endroit où le sang circule le plus vite, à débit constant.","aide":"À débit constant, une section plus petite oblige le sang à aller plus vite.","type":"zone","document":"artere","multiple":false},{"enonce":"Le débit dans la carotide est D = 6,0 cm³/s. Dans la partie normale, la section vaut 0,30 cm². Calcule la vitesse du sang, en cm/s.","aide":"D = v × S, donc v = D / S.","type":"nombre","unite":"cm/s"},{"enonce":"Dans le rétrécissement, la section n’est plus que de 0,12 cm². Quelle est alors la vitesse du sang, en cm/s ?","aide":"Le débit reste le même : utilise encore v = D / S avec la nouvelle section.","type":"nombre","unite":"cm/s"},{"enonce":"Touche la mesure de tension systolique la plus élevée du tableau.","aide":"Compare seulement le premier nombre de chaque case (la systolique).","type":"zone","document":"tension","multiple":false},{"enonce":"Que peut-on dire de ces six mesures ?","aide":"Rappelle-toi le seuil de l’hypertension et la notion de mesures répétées.","type":"choix","options":[{"id":"a","texte":"On ne peut rien dire : une tension ne se mesure qu’à l’hôpital"},{"id":"b","texte":"Elles sont toutes normales, car elles restent sous 12/8"},{"id":"c","texte":"Chacune atteint le seuil 14/9 : elles évoquent une hypertension durable"},{"id":"d","texte":"Une seule dépasse 14/9, donc ce n’est qu’un accident"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"D = v × S est constant : là où la section est la plus petite, **dans le rétrécissement**, la vitesse est la plus grande."},{"cle":{"type":"nombre","valeur":20,"tolerance":0.1},"affichage":"20 cm/s","explication":"v = D / S = 6,0 / 0,30 = **20 cm/s**."},{"cle":{"type":"nombre","valeur":50,"tolerance":0.1},"affichage":"50 cm/s","explication":"v = 6,0 / 0,12 = **50 cm/s** : la section a été divisée par 2,5, la vitesse est multipliée par 2,5."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La plus haute systolique est **16** (mercredi soir : 16/10), soit 160 mmHg."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les six mesures sont **supérieures ou égales à 14/9** : cette tension élevée est durable. Le diagnostic revient au médecin."}]$ex$::jsonb),
