ois flacons du rayon","colonnes":["Flacon","Formule semi-développée"],"lignes":[["X","CH₃–CH(OH)–COOH"],["Y","CH₃–CH₂–COOH"],["Z","HO–CH₂–CH₂–COOH"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le groupe hydroxyle –OH porté par le carbone central.","aide":"Cherche un O relié à un H, au-dessus du carbone du milieu.","type":"zone","document":"lactique","multiple":false},{"enonce":"Touche le groupe carboxyle –COOH.","aide":"Il se trouve à l’extrémité de la molécule : un C avec un O double et un O–H.","type":"zone","document":"lactique","multiple":false},{"enonce":"Combien d’atomes d’hydrogène l’acide lactique compte-t-il en tout sur ce schéma ?","aide":"Compte chaque H dessiné : sur les carbones et sur les deux oxygènes.","type":"nombre","unite":"atomes"},{"enonce":"Parmi Y et Z, quel flacon contient un isomère de l’acide lactique (flacon X) ?","aide":"Écris la formule brute de chaque flacon : l’isomère doit avoir exactement la même que X.","type":"choix","options":[{"id":"a","texte":"Y et Z : ils ont tous deux trois carbones"},{"id":"b","texte":"Aucun des deux : les isomères ont des formules brutes différentes"},{"id":"c","texte":"Seulement Z : C₃H₆O₃ comme X, mais avec une formule développée différente"},{"id":"d","texte":"Seulement Y : il a trois carbones comme X"}],"multiple":false},{"enonce":"Complète le nom des fonctions présentes dans l’acide lactique.","aide":"Rappelle-toi : C–OH est la marque d’une famille, –COOH celle d’une autre.","type":"trous","segments":["Le groupe –OH sur le carbone central est une fonction ",0," ; le groupe –COOH est une fonction ",1,"."],"banque":["cétone","amine","alcool","acide carboxylique"]}]}$ex$::jsonb,
