pe":"choix","options":[{"id":"a","texte":"22 %"},{"id":"b","texte":"4,5 %"},{"id":"c","texte":"44 %"},{"id":"d","texte":"78 %"}],"multiple":false},{"enonce":"Quelle masse de glucides (17 kJ par gramme) fournit l’énergie chimique consommée ? Arrondis à l’unité, en grammes.","aide":"Divise l’énergie consommée par l’énergie apportée par un gramme de glucides.","type":"nombre","unite":"g"}]}$ex$::jsonb,
